Becker:
:root{--well:#0f1722;--ink2:#cbd5e1;--line2:#283243;--glass:rgba(16,24,36,.96);--rad:12px}
html[data-theme=deportivo]{--bg:#0a1a36;--card:#10244a;--card2:#163059;--line:#28477a;--ink:#eef3fb;--mut:#9db0cf;--gold:#f6b93b;--teal:#36c5d6;--well:#0c1f42;--ink2:#d4def0;--line2:#2c4c80;--glass:rgba(14,32,66,.96)}
html[data-theme=claro]{--bg:#eef2f7;--card:#ffffff;--card2:#f4f6fa;--line:#d6dde7;--ink:#172033;--mut:#5c6a7e;--gold:#b7791f;--teal:#1f8f84;--red:#c53030;--green:#2f855a;--blue:#2b6cb0;--well:#eef2f7;--ink2:#2d3748;--line2:#cbd5e0;--glass:rgba(255,255,255,.96)}
html[data-theme=amigable]{--bg:#fff6ec;--card:#ffffff;--card2:#fff0e0;--line:#f0d8c0;--ink:#3b2a1e;--mut:#8b6d58;--gold:#e0781b;--teal:#2a9d8f;--red:#d1495b;--green:#3a9d5d;--blue:#3a7bd5;--well:#fff3e6;--ink2:#4a3626;--line2:#ecd2b8;--glass:rgba(255,255,255,.96);--rad:18px}
html[data-theme=retro]{--bg:#040904;--card:#081208;--card2:#0d1c0d;--line:#1e4a1e;--ink:#b6f7ae;--mut:#5fae58;--gold:#ffcc33;--teal:#4be0c0;--red:#ff5d5d;--green:#7dff6e;--blue:#6ec3ff;--well:#061006;--ink2:#a4e89c;--line2:#1b401b;--glass:rgba(6,16,6,.96);--rad:2px}
html[data-theme=medieval]{--bg:#e8dbbd;--card:#f4ead2;--card2:#ecdfbf;--line:#c4ab7c;--ink:#3a2814;--mut:#6e5638;--gold:#8f5a0f;--teal:#3d6b5a;--red:#8e1f1f;--green:#3f6b2a;--blue:#2c4f7c;--well:#efe2c4;--ink2:#4a3620;--line2:#c9b183;--glass:rgba(244,234,210,.97);--rad:6px}
html[data-theme=neon]{--bg:#09051a;--card:#120b28;--card2:#1a1036;--line:#3a2470;--ink:#f3edff;--mut:#a897d4;--gold:#ff3ea5;--teal:#22e1ff;--red:#ff4d6d;--green:#3dffb0;--blue:#22e1ff;--well:#0d0820;--ink2:#e2d8ff;--line2:#3c2775;--glass:rgba(18,11,40,.96)}
html[data-theme=retro] body,html[data-theme=retro] button,html[data-theme=retro] input,html[data-theme=retro] select{font-family:"Courier New",ui-monospace,monospace!important}
html[data-theme=medieval] body,html[data-theme=medieval] button,html[data-theme=medieval] input,html[data-theme=medieval] select{font-family:Georgia,"Times New Roman",serif!important}
html[data-theme=amigable] body,html[data-theme=amigable] button{font-family:"Trebuchet MS","Segoe UI Rounded",system-ui,sans-serif!important}
html[data-theme=claro] .bottom,html[data-theme=amigable] .bottom,html[data-theme=medieval] .bottom{box-shadow:0 -4px 14px rgba(0,0,0,.12)}
html[data-theme=claro] .overlay,html[data-theme=amigable] .overlay,html[data-theme=medieval] .overlay{background:rgba(30,30,40,.28)}
.card,.sheet,.modal,.item,.wkc,.opt{border-radius:var(--rad)}
html[data-theme=medieval] h2,html[data-theme=medieval] h3{letter-spacing:.04em}
html[data-theme=retro] .card,html[data-theme=retro] .sheet{box-shadow:0 0 0 1px #1e4a1e,0 0 18px rgba(80,255,80,.08)}
html[data-theme=neon] .btn.gold,html[data-theme=neon] #ageBtn{box-shadow:0 0 14px rgba(255,62,165,.55)}
/* piezas que tenían colores oscuros fijos y deben seguir el tema */
.nav{background:var(--card)!important;background-image:none!important;color:var(--ink)!important}
.nav.on{background:var(--well)!important;color:var(--gold)!important}
#clk .in{background:var(--glass)!important;border-color:var(--line2)!important}
#clk button{color:var(--mut)!important}#clk button.on{background:var(--gold)!important;color:#fff!important}
html[data-theme=noche] #clk button.on,html[data-theme=deportivo] #clk button.on,html[data-theme=retro] #clk button.on{color:#1a1405!important}
#clk .ci{color:var(--ink2)!important}
html[data-theme=claro] #clk .ci,html[data-theme=amigable] #clk .ci,html[data-theme=medieval] #clk .ci{text-shadow:none!important}
#topCard,#topCard .name,#topCard b{color:#eef2f7}#topCard .sub,#topCard small{color:#c9d3df}
.bt{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.bt button{flex:1 1 auto;border:1px solid var(--line2);background:var(--card2);color:var(--ink);border-radius:9px;padding:7px 8px;font-size:12.5px}
.bt button.g{border-color:var(--gold);color:var(--gold);font-weight:800}.bt button:disabled{opacity:.4}
html[data-theme=claro] .who,html[data-theme=amigable] .who,html[data-theme=medieval] .who{color:var(--ink)}
/* ===== vista horizontal: mapa grande a la izquierda y paneles a la derecha ===== */
body.land .app{max-width:none;display:grid;grid-template-columns:minmax(0,1fr) minmax(330px,34vw);grid-auto-rows:min-content;column-gap:10px;align-items:start;padding:8px 10px calc(var(--navh) + 10px)}
body.land .app>*{grid-column:2}
body.land .app>.mapcard{grid-column:1;grid-row:1 / span 30;position:sticky;top:8px;margin:0}
body.land #mapWrap{width:100%!important;max-width:none!important;aspect-ratio:auto!important;height:calc(100vh - var(--navh) - 34px)}
body.land #map,body.land #lc,body.land #glc,body.land #mapOv{aspect-ratio:auto!important;width:100%!important;height:100%!important}
body.land .bottom{padding:4px 10px calc(4px + env(safe-area-inset-bottom))}
body.land .bottom .in{grid-template-columns:repeat(5,minmax(0,112px));justify-content:center;gap:6px}
body.land #clk{flex-direction:row!important;gap:10px!important;margin:0 0 4px!important}
body.land .nav{flex-direction:row;justify-content:center;gap:5px;padding:6px 4px;font-size:12px}
body.land #ageBtn{padding:9px 4px;font-size:14px;border-radius:12px}
body.land .sheet{left:auto;right:0;top:0;width:min(460px,42vw);max-height:none;border-radius:16px 0 0 16px;transform:translateX(105%);border-left:1px solid var(--line)}
body.land .sheet.on{transform:translateX(0)}
body.land .overlay{background:transparent}
body.land .bottom .in{max-width:760px}

#cover{position:fixed;inset:0;z-index:80;overflow:hidden;background:#04070d;color:#eef3f8;opacity:0;transition:opacity .3s ease;font-family:system-ui,-apple-system,'Segoe UI',sans-serif}
#cover.on{opacity:1}body.cvon #toast.on{z-index:95}body.cvon{overflow:hidden}
#cvC{position:absolute;inset:0;width:100%;height:100%;display:block}
.cv-shade{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(3,6,12,.55) 0%,rgba(3,6,12,0) 28%,rgba(3,6,12,0) 50%,rgba(3,6,12,.82) 78%,rgba(3,6,12,.94) 100%)}
.cv-logo{direction:ltr}.cv-in{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:space-between;padding:calc(env(safe-area-inset-top) + 9vh) 18px calc(env(safe-area-inset-bottom) + 14px);max-width:560px;margin:0 auto;overflow-y:auto}
.cv-mid{text-align:center}
.cv-logo{margin:0;font-size:clamp(40px,12.5vw,76px);font-weight:900;letter-spacing:.14em;line-height:1;display:flex;justify-content:center;align-items:center;padding-left:.14em;
 background:linear-gradient(180deg,#fff7dd 0%,#f2c14e 55%,#b9852a 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 3px 14px rgba(0,0,0,.55))}
.cv-logo span,.cv-logo b{display:inline-block;animation:cvIn .7s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i)*70ms + 120ms)}
.cv-glb{width:.86em;height:.86em;fill:none;stroke:#f2c14e;stroke-width:6.5;vertical-align:-.04em;margin:0 .02em;filter:drop-shadow(0 0 8px rgba(242,193,78,.45))}
@keyframes cvIn{from{opacity:0;transform:translateY(-.35em) scale(.9)}to{opacity:1;transform:none}}
.cv-tag{margin-top:12px;font-size:15px;color:#d9e2ec;text-shadow:0 1px 6px rgba(0,0,0,.8);animation:cvIn .8s .7s both}
.cv-act{display:grid;gap:9px;animation:cvIn .7s .5s both}
.cv-cont{display:flex;align-items:center;gap:12px;width:100%;text-align:left;padding:10px 14px;border-radius:16px;border:1px solid rgba(242,193,78,.75);background:linear-gradient(135deg,rgba(242,193,78,.95),rgba(214,150,40,.95));color:#1b1204;box-shadow:0 8px 26px rgba(0,0,0,.45)}
.cv-cont .face{border-radius:50%;flex:0 0 auto;background:rgba(255,255,255,.35)}.cv-ct{flex:1;min-width:0}.cv-ct b{display:block;font-size:17px}.cv-ct small{display:block;font-size:12.5px;opacity:.85;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cv-cont i{font-style:normal;font-size:20px}
.cv-b{width:100%;padding:13px 14px;border-radius:14px;border:1px solid rgba(255,255,255,.18);background:rgba(10,16,26,.66);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);color:#eef3f8;font-weight:700;font-size:15.5px}
.cv-b.gold{background:linear-gradient(135deg,#f2c14e,#d49a2a);color:#1b1204;border-color:#f2c14e}.cv-b.sm{width:auto;flex:0 0 auto;padding:10px 12px;font-size:13px;align-self:flex-end}
.cv-b:active,.cv-cont:active{transform:scale(.98)}
.cv-row{display:flex;gap:8px;align-items:flex-end}.cv-lang{flex:1}.cv-lang .f{color:#c9d3df;font-size:12px}.cv-lang select{width:100%;padding:9px;border-radius:12px;background:rgba(10,16,26,.7);color:#eef3f8;border:1px solid rgba(255,255,255,.18)}
.cv-sty{margin-top:2px}.cv-sl{display:block;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#aeb9c6;margin-bottom:5px}
.cv-chips{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none}.cv-chips button{flex:0 0 auto;padding:7px 11px;border-radius:999px;border:1px solid rgba(255,255,255,.2);background:rgba(10,16,26,.6);color:#dfe7ef;font-size:13px;font-weight:600}
.cv-chips button.on{border-color:#f2c14e;color:#f2c14e;box-shadow:0 0 0 1px #f2c14e inset}
.cv-foot{display:flex;justify-content:space-between;font-size:11.5px;color:#9aa7b6}.cv-ld{animation:cvBl 1.2s ease-in-out infinite}@keyframes cvBl{50%{opacity:.4}}
.cv-cr{position:absolute;inset:0;z-index:2;display:none;padding:calc(env(safe-area-inset-top) + 24px) 20px 24px;overflow:auto;background:rgba(4,8,14,.94);font-size:14px;line-height:1.45}
#cover.cr .cv-cr{display:block}.cv-cr h2{margin:0 0 12px}.cv-cr p{margin:0 0 14px;color:#cdd6e0}.cv-cr b{color:#f2c14e}
.cv-tick{position:absolute;left:0;right:0;top:env(safe-area-inset-top);height:26px;overflow:hidden;background:rgba(0,0,0,.55);border-bottom:1px solid rgba(60,207,142,.35);font:12px ui-monospace,Menlo,monospace;color:#cfe;white-space:nowrap;z-index:1}
.cv-tick>div{display:inline-block;padding-top:5px;animation:cvTk 60s linear infinite}.cv-tick span{margin:0 16px}.cv-tick .up{color:#3ccf8e}.cv-tick .dn{color:#ff6b6b}@keyframes cvTk{to{transform:translateX(-50%)}}
.cv-mercados .cv-logo{background:linear-gradient(180deg,#e9fff4,#3ccf8e 60%,#1a8c5a);-webkit-background-clip:text;background-clip:text;font-family:ui-monospace,Menlo,Consolas,monospace;letter-spacing:.1em}
.cv-mercados .cv-glb{stroke:#3ccf8e;filter:drop-shadow(0 0 8px rgba(60,207,142,.5))}.cv-mercados .cv-cont{background:linear-gradient(135deg,#3ccf8e,#1f9d66);border-color:#3ccf8e;color:#03140c}
.cv-mercados .cv-b.gold{background:linear-gradient(135deg,#3ccf8e,#1f9d66);border-color:#3ccf8e;color:#03140c}.cv-mercados .cv-chips button.on{border-color:#3ccf8e;color:#3ccf8e;box-shadow:0 0 0 1px #3ccf8e inset}
.cv-planeta .cv-logo{background:linear-gradient(180deg,#ffffff,#cfe8ff 60%,#7fb7ea);-webkit-background-clip:text;background-clip:text}.cv-planeta .cv-glb{stroke:#cfe8ff;filter:drop-shadow(0 0 10px rgba(127,183,234,.6))}
.cv-planeta .cv-shade{background:linear-gradient(180deg,rgba(2,8,20,.5) 0%,rgba(2,8,20,0) 30%,rgba(2,8,20,0) 48%,rgba(2,8,20,.8) 76%,rgba(2,8,20,.94) 100%)}
.cv-atlas{color:#2b1d0e}.cv-atlas .cv-shade{background:radial-gradient(ellipse at 50% 42%,rgba(0,0,0,0) 45%,rgba(60,36,12,.45) 100%),linear-gradient(180deg,rgba(240,226,190,0) 50%,rgba(236,220,182,.88) 80%,rgba(232,214,174,.96) 100%)}
.cv-atlas .cv-logo{font-family:Georgia,'Times New Roman',serif;font-weight:700;letter-spacing:.12em;background:linear-gradient(180deg,#6b3a14,#3a1f08);-webkit-background-clip:text;background-clip:text;filter:drop-shadow(0 1px 0 rgba(255,240,200,.7))}
.cv-atlas .cv-glb{stroke:#6b3a14;filter:none}.cv-atlas .cv-tag{color:#3a2610;text-shadow:0 1px 0 rgba(255,245,215,.8);font-family:Georgia,serif;font-style:italic}
.cv-atlas .cv-b{background:rgba(248,238,212,.86);color:#3a2610;border-color:rgba(107,58,20,.45)}.cv-atlas .cv-b.gold,.cv-atlas .cv-cont{background:linear-gradient(135deg,#8a2e14,#5e1c0a);color:#fbecc9;border-color:#5e1c0a}
.cv-atlas .cv-lang .f,.cv-atlas .cv-sl,.cv-atlas .cv-foot{color:#5a4024}.cv-atlas .cv-lang select{background:rgba(248,238,212,.9);color:#3a2610;border-color:rgba(107,58,20,.45)}
.cv-atlas .cv-chips button{background:rgba(248,238,212,.85);color:#3a2610;border-color:rgba(107,58,20,.4)}.cv-atlas .cv-chips button.on{border-color:#8a2e14;color:#8a2e14;box-shadow:0 0 0 1px #8a2e14 inset}
.cv-rose{position:absolute;right:16px;top:calc(env(safe-area-inset-top) + 14px);width:74px;height:74px;color:#6b3a14;opacity:.75;z-index:1}.cv-ndl{animation:cvRo 14s ease-in-out infinite alternate;transform-origin:0 0}@keyframes cvRo{from{transform:rotate(-8deg)}to{transform:rotate(8deg)}}
@media (orientation:landscape) and (min-width:700px){.cv-in{max-width:none;flex-direction:row;align-items:center;padding:24px 4vw}.cv-mid{flex:1;text-align:left}.cv-logo{justify-content:flex-start}.cv-act{width:min(420px,42vw)}}
@media (prefers-reduced-motion:reduce){.cv-logo span,.cv-logo b,.cv-tag,.cv-act{animation:none}.cv-tick>div,.cv-ndl{animation:none}}
/* burbuja del mapa */
.mpop{position:absolute;z-index:6;width:min(300px,calc(100% - 12px));background:var(--glass,rgba(13,20,29,.96));border:1px solid var(--line,#2b3a4e);border-radius:14px;padding:9px 10px 8px;box-shadow:0 10px 28px rgba(0,0,0,.5);
 opacity:0;transform:translateY(6px) scale(.97);transform-origin:var(--ax) 100%;transition:opacity .16s ease,transform .18s cubic-bezier(.2,.8,.2,1);color:var(--ink,#e8eef6)}
.mpop.on{opacity:1;transform:none}.mpop.below{transform-origin:var(--ax) 0}
.mpop::after{content:'';position:absolute;left:var(--ax);bottom:-7px;width:12px;height:12px;margin-left:-6px;background:inherit;border-right:1px solid var(--line,#2b3a4e);border-bottom:1px solid var(--line,#2b3a4e);transform:rotate(45deg)}
.mpop.below::after{bottom:auto;top:-7px;transform:rotate(225deg)}
.mph{display:flex;align-items:center;gap:7px}.mpn{flex:1;min-width:0;line-height:1.2}.mpn b{display:block;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mpn small{color:var(--mut);font-size:11.5px}
.mpx{border:none;background:none;color:var(--mut);font-size:15px;padding:2px 4px}
.mpcs{display:flex;flex-wrap:wrap;gap:4px 10px;margin:6px 0 4px;font-size:12.5px}.mpc b{font-weight:800}.mpc small{color:var(--mut)}
.mpt{display:flex;flex-wrap:wrap;gap:4px;margin:2px 0 4px}.mpt span{font-size:11px;padding:2px 7px;border-radius:999px;background:var(--card2);border:1px solid var(--line);color:var(--ink2,#cbd5e1)}
.mpa{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:5px}.mpa button,.pla button{display:flex;flex-direction:column;align-items:center;gap:2px;padding:7px 3px 6px;border-radius:11px;border:1px solid var(--line);background:var(--card2);color:var(--ink);font-size:11px;font-weight:600;line-height:1.15;min-height:52px}
.mpa button i,.pla button i{font-style:normal;font-size:19px;line-height:1.1}.mpa button span,.pla button span{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.mpa button:first-child{border-color:var(--gold);color:var(--gold)}.mpa button:active,.pla button:active{transform:scale(.95)}.pla button:disabled{opacity:.42}
body.mapfull.mpopon #selInfo{display:none}
/* ficha del lugar */
.plh{display:flex;align-items:center;gap:10px}.pln{flex:1;min-width:0}.pln h3,.pln h4{margin:0}.pln small{color:var(--mut);font-size:12.5px}
.plx{border:1px solid var(--line);background:var(--card2);color:var(--ink);border-radius:999px;padding:6px 10px;font-size:12.5px;font-weight:700;white-space:nowrap}.plx.on{border-color:var(--teal);color:var(--teal)}
.pltabs{margin:8px 0 8px}.plg{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:4px 0 8px}
.plt{background:var(--card2);border:1px solid var(--line);border-radius:11px;padding:7px 8px;min-width:0}.plt small{display:block;color:var(--mut);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.plt b{font-size:15px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.plt i{font-style:normal;font-size:10.5px;color:var(--mut)}
.pla{display:grid;grid-template-columns:repeat(auto-fill,minmax(86px,1fr));gap:6px;margin:6px 0 10px}
.plex{display:grid;gap:6px;margin:4px 0 10px}.ple{font-size:12.5px;line-height:1.4;background:rgba(60,207,142,.06);border-left:3px solid var(--teal);border-radius:6px;padding:6px 9px;color:var(--ink2,#cbd5e1)}.ple b{display:block;color:var(--ink);font-size:12.5px}
.plr{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:8px}.plnf{line-height:1.55}
.plcy{border:1px solid var(--gold);border-radius:12px;padding:9px 10px;margin-bottom:10px;background:rgba(242,193,78,.05)}
.item.on{border-color:var(--gold)}
.renb{border:1px solid var(--line);background:var(--card2);border-radius:8px;padding:1px 6px;font-size:13px;vertical-align:2px;margin-left:4px;cursor:pointer}
/* barra del mes y lo próximo (solo con el avance automático) */
#mnx{position:fixed;left:10px;bottom:calc(var(--navh) + 8px);z-index:12;max-width:calc(100% - 150px);height:26px;border-radius:999px;overflow:hidden;background:var(--glass,rgba(12,18,26,.92));border:1px solid var(--line2,#2b3a4e);
 display:flex;align-items:center;font-size:12px;font-weight:600;color:var(--ink,#e8eef6);opacity:0;transform:translateY(8px);pointer-events:none;transition:opacity .2s,transform .2s}
#mnx.on{opacity:1;transform:none;pointer-events:auto}#mnx>i{position:absolute;left:0;top:0;bottom:0;background:linear-gradient(90deg,rgba(60,207,142,.28),rgba(60,207,142,.45));transition:width .35s linear}
#mnx>span{position:relative;padding:0 11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}body.mapfull #mnx{bottom:calc(var(--navh) + 8px)}
/* 👥 vida social */
#clk .ap #vsB{position:relative;min-width:30px;padding:0 6px!important}#clk .ap #vsB::after{content:'';position:absolute;right:3px;top:3px;width:7px;height:7px;border-radius:50%;background:#7b8794;box-shadow:0 0 0 1.5px var(--glass,#0c121a)}
#clk .ap #vsB.vsg::after{background:#3ccf8e}#clk .ap #vsB.vsa::after{background:#f2c14e}#clk .ap #vsB.vsr::after{background:#ff5a5f}

:root{--fs-1:11px;--fs-2:12.5px;--fs-3:13.5px;--fs-4:15px;--fs-5:17px;--fs-6:20px;--fs-7:26px;--sp-1:4px;--sp-2:8px;--sp-3:12px;--sp-4:16px;--sp-5:24px;
 --r-s:9px;--r-m:12px;--r-l:16px;--r-p:999px;--sh-1:0 1px 2px rgba(0,0,0,.18),0 2px 8px rgba(0,0,0,.12);--sh-2:0 10px 30px rgba(0,0,0,.35);
 --dur-1:.12s;--dur-2:.2s;--dur-3:.32s;--ease:cubic-bezier(.2,.8,.2,1);--tap:40px;--focus:var(--teal)}
html,body{font-size:var(--fs-4);line-height:1.45;-webkit-font-smoothing:antialiased}
.sheet h3{font-size:var(--fs-5);font-weight:800;letter-spacing:.1px}.modal h2{font-size:var(--fs-6);font-weight:800}
.sheet .hint,.hint{line-height:1.45}.sect{font-size:11.5px;letter-spacing:.08em;font-weight:700}
/* botones: tamaño mínimo de toque, estados claros (presionado, foco, desactivado) */
.btn,.item,.opt,.ntabs button,.vtabs button,.seg button,.chips button,.mkt button,.nav,#ageBtn,.cv-b,.mpa button,.pla button,.bt button{transition:background-color var(--dur-2) var(--ease),border-color var(--dur-2) var(--ease),color var(--dur-2) var(--ease),transform var(--dur-1) var(--ease),box-shadow var(--dur-2) var(--ease)}
.btn{min-height:38px;border-radius:var(--r-s);font-weight:600}
.btn:not(:disabled):active,.item:not(:disabled):active,.opt:active,.ntabs button:active,.vtabs button:active,.seg button:active,.chips button:active,.mkt button:active,.nav:active,.cv-b:active{transform:scale(.97)}
.btn.gold,.seg button.on,.vtabs button.on,.badge2{background:var(--act)!important;color:var(--act-ink)!important;border-color:var(--act)!important}
#ageBtn{background:var(--act);color:var(--act-ink);box-shadow:0 6px 20px color-mix(in srgb,var(--act) 30%,transparent)}
#clk button.on{background:var(--act)!important;color:var(--act-ink)!important}
.btn.red{border-color:var(--red);color:var(--red)}
.btn:disabled,.item:disabled,.opt:disabled,.nav:disabled{opacity:.45;filter:saturate(.6);cursor:not-allowed}
:where(button,[role=button],select,input,a):focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.item{min-height:48px}.item:not(:disabled):hover{border-color:var(--line2)}
.item .s,.item .r{color:var(--mut)}
/* pestañas: la elegida con fondo tenue y el acento; las demás sin ruido */
.ntabs button{min-height:34px;color:var(--mut)}.ntabs button.on{background:var(--sel-bg);color:var(--gold);border-color:var(--sel-line);box-shadow:inset 0 -2px 0 var(--act)}
.chips button.on{background:var(--sel-bg);border-color:var(--sel-line);color:var(--gold)}
.mkt button.on{border-color:var(--sel-line)}
.nav.on{box-shadow:inset 0 0 0 1px var(--sel-line)}
.card{box-shadow:var(--sh-1)}.modal,.sheet{box-shadow:var(--sh-2)}
.lg.bad{color:var(--red)}.lg.good{color:var(--green)}
/* tarjeta «¿Sabías que…?» de la portada */
.cv-fact{display:grid;gap:3px;width:100%;text-align:left;padding:10px 13px 9px;border-radius:var(--r-m);border:1px solid rgba(242,193,78,.35);background:rgba(10,16,24,.72);color:#e8eef6;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);box-shadow:0 6px 20px rgba(0,0,0,.35);margin-bottom:2px;min-height:86px}
.cv-fl{font-size:11px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:#f2c14e}.cv-ft{font-size:14px;line-height:1.38}.cv-fs{font-size:11.5px;color:#a9b6c6}.cv-fs span+span{margin-inline-start:.35em}html[lang^=zh] .cv-fs span+span,html[lang=ja] .cv-fs span+span{margin-inline-start:.1em}
.cv-planeta .cv-fact{border-color:rgba(120,190,255,.35)}.cv-planeta .cv-fl{color:#8fc8ff}.cv-mercados .cv-fact{border-color:rgba(76,200,115,.4)}.cv-mercados .cv-fl{color:#6be38f}
.cv-atlas .cv-fact{background:rgba(250,240,214,.86);border-color:#a8792a;color:#2c1d0b;box-shadow:0 4px 14px rgba(60,40,10,.25)}.cv-atlas .cv-fl{color:#7a4a06}.cv-atlas .cv-fs{color:#5f4a2f}
/* vista horizontal: el mapa ocupa el alto disponible (la ficha de abajo se desplaza por dentro) y la barra de abajo cabe completa */
body.land .app>.mapcard{display:flex;flex-direction:column;height:calc(100vh - var(--navh) - 16px);overflow:hidden}
body.land .app>.mapcard #mapWrap{flex:1 1 auto;height:auto!important;min-height:0}
body.land .app>.mapcard #selInfo{flex:0 1 auto;max-height:32%;overflow-y:auto;overscroll-behavior:contain}
body.land .bottom .in{grid-template-columns:repeat(5,minmax(92px,132px))!important;max-width:820px}
body.land .nav{white-space:nowrap;min-width:0}body.land .nav .badge{font-size:11.5px}
body.land #clk .seg button,body.land #clk button{padding-top:4px;padding-bottom:4px}
body.land .sheet{top:6px;border-radius:var(--r-l) 0 0 var(--r-l)}
@media (orientation:landscape) and (max-height:440px){body.land .bottom{padding-top:2px}body.land .nav{padding:5px 4px}body.land #ageBtn{padding:7px 4px}}

/* íconos: vista previa en Ajustes */
.chips.ivs{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.chips.ivs button{display:grid;gap:2px;justify-items:center;padding:7px 4px;min-height:56px}
.ivp{font-size:14px;letter-spacing:.5px;white-space:nowrap;line-height:1.2;max-width:100%;overflow:hidden}.chips.ivs button>span:last-child{white-space:normal;line-height:1.15;font-size:12px}.ivp.j{font-family:IVIPJ,system-ui!important}.ivp.l{font-family:IVIPL,system-ui!important}.ivp.e{--emo:system-ui,"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif;font-family:var(--emo)!important}
.cv-aut{color:#a9b6c6;font-size:11.5px}
/* Lottie */
#lotfx{position:fixed;left:50%;top:34%;width:min(58vw,250px);aspect-ratio:1;transform:translate(-50%,-50%) scale(.92);opacity:0;pointer-events:none;z-index:9990;transition:opacity .18s ease,transform .3s var(--ease,ease)}
#lotfx.on{opacity:1;transform:translate(-50%,-50%) scale(1)}#lotfx.off{opacity:0;transform:translate(-50%,-56%) scale(.96)}
.lot-bg{position:absolute;inset:16%;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--card) 88%,transparent) 0,color-mix(in srgb,var(--card) 50%,transparent) 55%,transparent 72%)}
.lot-c{position:absolute;inset:0}.lot-c svg{display:block}
.lot-t{position:absolute;left:0;right:0;bottom:-2%;text-align:center;font-weight:900;font-size:var(--fs-6,20px);letter-spacing:.02em;color:var(--gold);text-shadow:0 2px 10px color-mix(in srgb,var(--bg) 85%,transparent),0 0 2px var(--bg)}
/* ejércitos en la burbuja */
.mpar{display:flex;gap:5px;flex-wrap:wrap;margin:5px 0 2px}
.mparm{width:auto!important;flex:0 0 auto;display:inline-flex!important;align-items:center;gap:4px;min-height:34px;padding:3px 9px 3px 7px;border-radius:var(--r-p,999px);border:1px solid var(--line);background:var(--card2);color:var(--ink);font-size:12.5px}
.mparm i{font-style:normal;font-size:14px}.mpmo{display:block;width:22px;height:5px;border-radius:3px;background:var(--well);overflow:hidden;text-decoration:none}.mpmo u{display:block;height:100%;border-radius:3px}.mparm em{font-style:normal;font-size:12px}
.mparm.on{border-color:var(--sel-line);background:var(--sel-bg);box-shadow:inset 0 -2px 0 var(--act)}.mparm.on b{color:var(--gold)}
.mpa.mpord{margin-top:4px}.mpa.mpord button:first-child{background:var(--act);color:var(--act-ink);border-color:var(--act)}.mpa.mpord button:first-child span,.mpa.mpord button:first-child i{color:var(--act-ink)}
.mph{font-size:12px;color:var(--mut);margin:3px 0 1px}
.mpordh{position:absolute;left:8px;right:8px;top:8px;margin:0 auto;width:fit-content;z-index:6;display:flex;align-items:center;gap:6px;background:var(--glass);border:1px solid var(--sel-line);color:var(--ink);border-radius:var(--r-m,12px);padding:5px 6px 5px 10px;font-size:12.5px;box-shadow:var(--sh-2)}
.mpordh .btn.sm{min-height:30px;padding:3px 10px;font-size:12px}
body.mapfull .mpordh{top:calc(54px + env(safe-area-inset-top))}
/* tarjetas de datos en las pantallas viejas */
.v19g{grid-template-columns:repeat(3,1fr)}.v19g .plt small{white-space:normal;line-height:1.2;overflow:visible}.v19g .plt i{display:block;line-height:1.25}.v19g .plt b{font-size:14.5px;white-space:normal;overflow-wrap:anywhere;line-height:1.2}.v19g.c2{grid-template-columns:1fr 1fr}
@media (max-width:360px){.v19g{grid-template-columns:1fr 1fr}}
.v19gov{font-size:12.5px;color:var(--mut);margin:-2px 0 6px}
.mpt.v19rel{display:flex;flex-wrap:wrap;gap:5px;margin:2px 0 8px}.mpt.v19rel>span,.mpt.v19rel .pill{font-size:12px;padding:3px 9px;border-radius:var(--r-p,999px);border:1px solid var(--line);background:var(--card2);color:var(--ink2)}
.v19dip{display:flex;gap:12px;align-items:center;background:var(--card2);border:1px solid var(--line);border-radius:var(--r-m,12px);padding:8px 10px;margin:4px 0 8px}
.v19dip b{display:block;font-size:13.5px;color:var(--ink)}.v19dip span{display:block;font-size:12px;color:var(--mut);margin-top:2px}
.v19pip{display:flex;gap:4px;flex:0 0 auto}.v19pip i{width:12px;height:12px;border-radius:50%;border:2px solid var(--sel-line);background:transparent}.v19pip i.on{background:var(--act);border-color:var(--act)}
/* Resumen del país: mismas tarjetas que la ficha del lugar */
.ngrid{gap:6px}.nst{border-radius:11px;padding:7px 9px;gap:1px}.nst>span{font-size:11px;color:var(--mut)}.nst b{font-size:15px;font-weight:700;background:none!important;padding:0!important;text-align:start!important}
.nst b.pos{color:var(--green)}.nst b.neg{color:var(--red)}
.ideo{border-width:1px 1px 1px 4px;border-radius:var(--r-m,12px);padding:9px 11px}
/* presupuesto */
.bud{border-radius:var(--r-m,12px);padding:8px 10px}.bctl .btn{min-width:var(--tap,40px);min-height:36px}.hb{background:var(--well);height:6px}
/* gabinete */
.v19mn{align-items:flex-start}.v19mn .ic{font-size:24px;padding-top:2px}.v19mn .tt>b{font-size:14px}.mnw{font-size:12px;color:var(--mut);margin:1px 0 4px}
.mnms{display:grid;gap:3px;margin:2px 0 4px}.mnm{display:grid;grid-template-columns:minmax(76px,auto) 1fr 28px;align-items:center;gap:8px;font-size:11.5px;color:var(--mut)}
.mnm em{font-style:normal;text-align:right;color:var(--ink);font-weight:700;font-size:12px}.mb2{display:block;height:6px;border-radius:3px;background:var(--well);overflow:hidden}.mb2 b{display:block;height:100%;border-radius:3px}
.v19mn .mini-actions{margin-top:4px}.v19mn .mini-actions .btn{min-height:34px;padding:5px 12px;font-size:12.5px}
/* ranking */
.item.rk1 .t,.item.rk2 .t,.item.rk3 .t{font-weight:800}.item.rk1{border-color:color-mix(in srgb,#e6b422 55%,var(--line))}.item.rk2{border-color:color-mix(in srgb,#b8c2cc 55%,var(--line))}.item.rk3{border-color:color-mix(in srgb,#c47a3a 55%,var(--line))}
.item.mine{border-color:var(--sel-line);background:var(--sel-bg)}
/* Bolsa: pestañas y tarjetas con el sistema de diseño */
.mkt{gap:5px}.mkt button{border-radius:var(--r-p,999px);border-color:var(--line);background:var(--card2);color:var(--mut);min-height:34px;padding:6px 10px;font-weight:700}
.mkt button.on{background:var(--sel-bg);color:var(--gold);border-color:var(--sel-line);box-shadow:inset 0 -2px 0 var(--act)}
.fin{border-radius:var(--r-m,12px);background:var(--card2)}.frow{min-height:34px;align-items:center}
.sheet h3 small{font-weight:600}
html[dir=rtl] .mnm em{text-align:left}

#pfx{position:fixed;inset:0;width:100vw;height:100vh;pointer-events:none;z-index:9985;display:none}
#drgL{position:fixed;inset:0;pointer-events:none;z-index:9980;display:none}#drgL.on{display:block}
#drgL svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
#drgL line{stroke:var(--act);stroke-width:3;stroke-dasharray:7 5;stroke-linecap:round;filter:drop-shadow(0 1px 2px rgba(0,0,0,.6))}
#drgL circle{fill:color-mix(in srgb,var(--act) 35%,transparent);stroke:var(--act);stroke-width:2.5}
#drgL.no line,#drgL.no circle{stroke:var(--mut)}#drgL.no circle{fill:transparent}
.drgT{position:absolute;transform:translateX(-50%);white-space:nowrap;background:var(--glass);border:1px solid var(--sel-line);color:var(--ink);border-radius:var(--r-p,999px);padding:4px 11px;font-size:13px;font-weight:700;box-shadow:var(--sh-2)}
#drgL.no .drgT{color:var(--mut);border-color:var(--line)}
/* Bancos */
.bnk .h{align-items:flex-start}.bnk .h b{min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:4px;line-height:1.25}
.bnk .h>span{white-space:nowrap;font-size:17px;font-weight:800;color:var(--gold);font-variant-numeric:tabular-nums}
.tier{white-space:nowrap;margin-left:0;max-width:100%;overflow:hidden;text-overflow:ellipsis}
.bnk .mpb button,.svc .mpb button{min-height:36px}
/* Mis empresas / Mesa: datos como tarjetas */
.kv.kvt{grid-template-columns:1fr 1fr;gap:6px;margin:8px 0}
.kv.kvt>div{flex-direction:column;justify-content:flex-start;align-items:flex-start;gap:1px;border:1px solid var(--line);background:var(--card2);border-radius:11px;padding:7px 9px;min-width:0}
.kv.kvt span{font-size:11px;line-height:1.25}.kv.kvt b{text-align:start;font-size:15px;font-weight:700;color:var(--ink);overflow-wrap:anywhere}
.kv.kvt b .up{color:var(--green)}.kv.kvt b .dn{color:var(--red)}.kv.kvt b span{font-size:inherit;font-weight:inherit}
.bzc{border-radius:var(--r-m,12px)}.bzc .h b{font-size:15.5px}.bzc .chg{font-weight:800;white-space:nowrap}
.svc{border-radius:var(--r-m,12px)}.svc .ic{font-size:24px;width:30px;text-align:center}

/* --- seguridad de pantalla (viewport-fit=cover) --- */
.app{padding-left:max(10px,env(safe-area-inset-left));padding-right:max(10px,env(safe-area-inset-right))}
body.land .app{padding-left:max(10px,env(safe-area-inset-left));padding-right:max(10px,env(safe-area-inset-right))}
.bottom{padding-left:max(10px,env(safe-area-inset-left));padding-right:max(10px,env(safe-area-inset-right))}
/* --- 2) toque mínimo de 44 px (sin cambiar el aspecto del tema Actual) --- */
.mini-actions .btn,.abx .btn,.plfx .btn{min-height:44px;touch-action:manipulation}
.btn,.item,.nav,#ageBtn{touch-action:manipulation}
.item{min-height:44px}
/* --- 3) burbujas de acciones --- */
.mini-actions.abub{position:relative;display:block;height:44px;margin-top:8px}
.abt{position:absolute;left:0;top:0;z-index:2;display:inline-flex;align-items:center;gap:5px;height:44px;min-width:44px;padding:0 12px;border-radius:22px;border:1px solid var(--gold);background:var(--card2);color:var(--gold);font-weight:800;font-size:15px;cursor:pointer;user-select:none;-webkit-user-select:none;touch-action:manipulation;box-shadow:0 3px 10px rgba(0,0,0,.28);transition:transform .16s cubic-bezier(.2,.8,.2,1),background .16s}
.abt:active{transform:scale(.94)}
.abt .abn{font-size:11.5px;font-weight:800;min-width:18px;height:18px;line-height:18px;text-align:center;border-radius:9px;background:var(--gold);color:#1a1405;padding:0 4px}
.abt .abc{display:inline-block;font-size:13px;line-height:1;transition:transform .2s cubic-bezier(.2,.8,.2,1)}
.abub.open .abt{background:var(--gold);color:#1a1405}.abub.open .abt .abn{background:#1a1405;color:var(--gold)}
.abx{position:absolute;left:var(--abw,64px);right:0;top:0;height:44px;display:flex;flex-wrap:nowrap;align-items:center;gap:6px;padding:0 10px 0 6px;overflow-x:auto;overflow-y:hidden;scroll-behavior:smooth;scroll-snap-type:x proximity;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch;scrollbar-width:none;
 opacity:0;transform:translateX(-14px);clip-path:inset(0 100% 0 0);visibility:hidden;pointer-events:none;transition:opacity .18s ease,transform .22s cubic-bezier(.2,.8,.2,1),clip-path .24s cubic-bezier(.2,.8,.2,1),visibility 0s linear .24s;
 -webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 22px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 22px),transparent)}
.abx::-webkit-scrollbar{display:none}
.abx>.btn,.abx>button{flex:0 0 auto;scroll-snap-align:start;white-space:nowrap}
.abub.open .abx{opacity:1;transform:none;clip-path:inset(0 0 0 0);visibility:visible;pointer-events:auto;transition-delay:0s}
/* --- 4) ficha de provincia/ciudad --- */
#selInfo.sil{background:var(--card2);border:1px solid var(--line);border-radius:14px;padding:10px 12px;box-shadow:0 6px 18px rgba(0,0,0,.26)}
#selInfo .sih{display:flex;align-items:center;gap:9px;margin-bottom:8px}
#selInfo .sitl{display:none}
#selInfo .sif{height:22px;width:auto;flex:none;border-radius:3px}
#selInfo .sit{flex:1;min-width:0;line-height:1.25;font-size:12px;color:var(--mut)}
#selInfo .sit .sin{display:block;font-size:17px;font-weight:800;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#selInfo .sik{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}
#selInfo .sic{display:inline-flex;align-items:center;gap:5px;padding:5px 10px;border-radius:999px;background:var(--card);border:1px solid var(--line);font-size:13px;color:var(--ink)}
#selInfo .sic b{font-weight:800}
#selInfo.sil .mem{font-size:12px}
#selInfo .plfx{display:flex;gap:6px;margin:0 0 8px}
#selInfo .plfx .btn{flex:1 1 0;min-width:0}
#selInfo .plfx .btn.gold{flex:2 1 0}
.mpop{border-radius:16px}
@media (prefers-reduced-motion:reduce){.abt,.abx,.abt .abc{transition:none!important}}
/* --- 1) vista horizontal con riel (iPhone en horizontal) --- */
html.rail{--navh:0px!important}
html.rail body.land .bottom{left:0;right:auto;top:0;bottom:0;width:calc(86px + env(safe-area-inset-left));padding:calc(6px + env(safe-area-inset-top)) 6px calc(6px + env(safe-area-inset-bottom)) calc(6px + env(safe-area-inset-left));background:var(--bg);border-right:1px solid var(--line);box-shadow:none}
html.rail body.land .bottom .in{max-width:none!important;height:100%;grid-template-columns:1fr!important;grid-auto-rows:minmax(44px,1fr);gap:5px;align-items:stretch;justify-content:stretch}
html.rail body.land #ageBtn{grid-column:auto;padding:6px 2px;font-size:13px;border-radius:14px;box-shadow:none}
html.rail body.land .nav{flex-direction:column;justify-content:center;gap:1px;padding:3px 2px;font-size:11px;min-height:44px;line-height:1.1}
html.rail body.land .nav .ic{font-size:17px}
html.rail body.land .app{grid-template-columns:minmax(0,1fr) minmax(300px,38vw);padding:calc(8px + env(safe-area-inset-top)) max(10px,env(safe-area-inset-right)) calc(10px + env(safe-area-inset-bottom)) calc(96px + env(safe-area-inset-left))}
html.rail body.land:not(.mapfull) .app>.mapcard{display:contents}
html.rail body.land:not(.mapfull) .app>.mapcard #mapWrap{grid-column:1;grid-row:1/span 30;position:sticky;top:calc(8px + env(safe-area-inset-top));align-self:start;flex:none;height:calc(100vh - 16px - env(safe-area-inset-top) - env(safe-area-inset-bottom))!important;height:calc(100dvh - 16px - env(safe-area-inset-top) - env(safe-area-inset-bottom))!important;border:1px solid var(--line)}
html.rail body.land:not(.mapfull) #cmdBar,html.rail body.land:not(.mapfull) #selInfo{grid-column:2;margin:0 0 10px}
html.rail body.land:not(.mapfull) #selInfo{max-height:none;overflow:visible}
html.rail body.mapfull #mapWrap{left:calc(86px + env(safe-area-inset-left));bottom:0}
html.rail body.mapfull #selInfo{left:calc(96px + env(safe-area-inset-left));right:calc(8px + env(safe-area-inset-right));bottom:calc(8px + env(safe-area-inset-bottom));max-width:48vw;max-height:46vh;max-height:46dvh}
html.rail .ff{right:calc(12px + env(safe-area-inset-right));bottom:calc(10px + env(safe-area-inset-bottom))}
html.rail #mnx{left:calc(96px + env(safe-area-inset-left));bottom:calc(10px + env(safe-area-inset-bottom))}
html.rail body.land .sheet{top:calc(6px + env(safe-area-inset-top));bottom:0;max-height:none!important;padding-right:calc(12px + env(safe-area-inset-right));padding-bottom:calc(14px + env(safe-area-inset-bottom))}
html.rail body.land .modal{left:calc(50% + 43px);max-height:calc(100vh - 16px)!important;max-height:calc(100dvh - 16px)!important;top:50%!important;width:min(calc(100vw - 120px),460px)}
/* --- estilo pixel (html[data-px=p2]) --- */
html[data-px=p2] :is(.mini-actions,.abx,.plfx) .btn{min-height:44px;padding:0 14px;font-family:var(--pxf);font-size:12.5px;letter-spacing:.02em;font-weight:700;background-color:var(--card2);box-shadow:inset 2px 2px 0 var(--px-hi),inset 0 -3px 0 var(--px-lo)!important}
html[data-px=p2] :is(.mini-actions,.abx,.plfx) .btn.gold{background:var(--gold);color:#1a1405;border-color:color-mix(in srgb,var(--gold) 45%,#000)!important;box-shadow:inset 2px 2px 0 rgba(255,255,255,.45),inset 0 -3px 0 rgba(0,0,0,.35)!important}
html[data-px=p2] :is(.mini-actions,.abx,.plfx) .btn.red{border-color:var(--red)!important}
html[data-px=p2] :is(.mini-actions,.abx,.plfx) .btn:disabled{opacity:.45;filter:saturate(.4)}
html[data-px=p2] .abt{border:2px solid var(--px-edge);clip-path:var(--px-cut);border-radius:0;box-shadow:inset 2px 2px 0 var(--px-hi),inset 0 -3px 0 var(--px-lo);font-family:var(--pxf);transition:transform 60ms steps(2,end)}
html[data-px=p2] .abt:active{transform:translateY(2px);filter:brightness(.92)}
html[data-px=p2] .abx{clip-path:inset(0 100% 0 0)}html[data-px=p2] .abub.open .abx{clip-path:inset(0 0 0 0)}
html[data-px=p2] #selInfo.sil{border:2px solid var(--px-edge);border-radius:0;background-color:var(--card2);box-shadow:inset 2px 2px 0 var(--px-hi),inset -2px -2px 0 var(--px-lo),0 3px 0 var(--px-slab,rgba(0,0,0,.4))}
html[data-px=p2] #selInfo .sic{border:2px solid var(--px-edge);border-radius:0;font-family:var(--pxn);font-size:12px;background:var(--card);box-shadow:inset 2px 2px 0 var(--px-hi),inset -2px -2px 0 var(--px-lo)}
html[data-px=p2] #selInfo .sit .sin{font-family:var(--pxf);font-size:15px;letter-spacing:.02em}
html[data-px=p2] #selInfo .sih{border-bottom:2px solid var(--px-edge);padding-bottom:8px;margin-bottom:8px}
html[data-px=p2] #selInfo .sif{border-radius:0;image-rendering:pixelated}
/* losa isométrica (la misma que el barrio de la prueba 3): cara de césped, canto de tierra y remate de tejado */
html[data-px=p2] #selInfo .sitl{display:block;position:relative;flex:none;width:30px;height:20px}
html[data-px=p2] #selInfo .sitl::before,html[data-px=p2] #selInfo .sitl::after{content:'';position:absolute;left:0;width:30px;height:16px;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
html[data-px=p2] #selInfo .sitl::before{top:4px;background:var(--c-roof,#a8473b)}
html[data-px=p2] #selInfo .sitl::after{top:0;background:linear-gradient(135deg,var(--c-grass,#5f9a3e) 0 50%,var(--c-grass2,#548b37) 50%)}
html[data-px=p2] .mpop{box-shadow:inset 2px 2px 0 var(--px-hi),inset -2px -2px 0 var(--px-lo),0 3px 0 var(--px-slab,rgba(0,0,0,.4))!important}
html[data-px=p2] .mpop::after{display:none}
html[data-px=p2].rail body.land .bottom,html[data-px=p2].rail body.land .bottom .in{background-image:none}
html[data-px=p2] .mpa button:first-child{box-shadow:inset 0 0 0 2px var(--gold),inset -2px -4px 0 var(--px-lo)!important}

/* ---------- 1) pestañas: una fila, trazo en la activa ---------- */
body :is(.ntabs,.mkt,.nwt){position:relative;display:flex;flex-wrap:nowrap;gap:0;margin:2px 0 10px;padding:0;overflow-x:auto;overflow-y:hidden;border:0;border-bottom:1px solid var(--line);border-radius:0;background:none;scrollbar-width:none;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain}
body :is(.ntabs,.mkt,.nwt)::-webkit-scrollbar{display:none}
body :is(.ntabs,.mkt,.nwt) button{position:relative;flex:1 0 auto;min-height:42px;margin:0;padding:0 12px;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;color:var(--mut)!important;font-size:13px;font-weight:650;white-space:nowrap;transition:color .16s ease}
body :is(.ntabs,.mkt,.nwt) button::after{content:'';position:absolute;left:10px;right:10px;bottom:0;height:2px;border-radius:2px 2px 0 0;background:var(--act,var(--gold));opacity:0;transform:scaleX(.3);transition:transform .2s cubic-bezier(.2,.8,.2,1),opacity .16s ease;pointer-events:none}
body :is(.ntabs,.mkt,.nwt) button.on{color:var(--ink)!important}
body :is(.ntabs,.mkt,.nwt) button.on::after{opacity:1;transform:none}
body :is(.ntabs,.mkt,.nwt) button:not(.on):active{color:var(--ink)!important}
/* subpestañas: pequeñas y ligeras */
body .chips:not(.ivs){position:relative;gap:5px;margin:2px 0 8px;padding:1px 0 3px;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}
body .chips:not(.ivs) button{min-height:34px;padding:0 10px;border:1px solid var(--line);background:transparent;border-radius:999px;font-size:12px;font-weight:600;color:var(--mut)}
body .chips:not(.ivs) button.on{color:var(--ink);border-color:var(--act,var(--gold));background:color-mix(in srgb,var(--act,#f2c14e) 13%,transparent)}
body .tfs{position:relative;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;gap:3px}
body .tfs::-webkit-scrollbar,body .chips::-webkit-scrollbar{display:none}
body .tfs button{flex:none;min-height:32px;padding:0 9px;border-color:transparent;background:transparent;font-size:11.5px;color:var(--mut)}
body .tfs button.on{color:var(--ink);border-color:transparent;box-shadow:inset 0 -2px 0 var(--act,var(--gold))}
/* opciones (.seg) y Personaje/País (.vtabs): grupo con tinte leve, sin relleno pesado */
body :is(.seg,.vtabs){gap:2px;padding:2px;border:1px solid var(--line);border-radius:11px;background:var(--card2)}
body :is(.seg,.vtabs) button{min-height:40px;border:0!important;border-radius:9px;background:transparent!important;color:var(--mut)!important;box-shadow:none}
body :is(.seg,.vtabs) button.on{background:color-mix(in srgb,var(--act,#f2c14e) 17%,transparent)!important;color:var(--ink)!important;box-shadow:inset 0 -2px 0 var(--act,var(--gold))!important}
body .seg button.on.sell{background:color-mix(in srgb,var(--red,#f0565d) 18%,transparent)!important;box-shadow:inset 0 -2px 0 var(--red,#f0565d)!important}
body .seg button:disabled{opacity:.35}
/* la fila que no cabe: desvanecido a la derecha mientras quede algo por ver */
body .v3ov:not(.v3ve){-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 22px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 22px),transparent)}
/* ⓘ de la pestaña: solo el botón, discreto */
.ibrow{margin:-4px 0 4px;min-height:0}.ibrow>span:first-child{display:none!important}
@media (prefers-reduced-motion:reduce){body :is(.ntabs,.mkt,.nwt) button::after{transition:none}}
/* pixel: trazo de 4 px (ventana encendida), sin bisel en las pestañas */
html[data-px=p2] body :is(.ntabs,.mkt,.nwt){border-bottom:2px solid var(--px-edge)}
html[data-px=p2] body :is(.ntabs,.mkt,.nwt) button{border:0!important;clip-path:none;box-shadow:none!important;background:none!important;min-height:42px;padding:0 10px;font-family:var(--pxf);font-size:12px}
html[data-px=p2] body :is(.ntabs,.mkt,.nwt) button::after{display:none}
html[data-px=p2] body :is(.ntabs,.mkt,.nwt) button.on{color:var(--ink)!important;box-shadow:inset 0 -4px 0 var(--c-lit,var(--gold))!important}
html[data-px=p2] body :is(.ntabs,.mkt,.nwt) button:not(:disabled):active{transform:translateY(1px)!important;filter:none}
html[data-px=p2] body .chips:not(.ivs) button{min-height:36px;padding:0 8px;background:transparent;box-shadow:none!important}
html[data-px=p2] body .chips:not(.ivs) button.on{background:color-mix(in srgb,var(--c-lit,#ffd166) 14%,transparent);box-shadow:inset 0 -4px 0 var(--c-lit,var(--gold))!important}
html[data-px=p2] body :is(.seg,.vtabs){border:2px solid var(--px-edge);border-radius:0;padding:2px}
html[data-px=p2] body :is(.seg,.vtabs) button{clip-path:none;border:0!important;border-radius:0;min-height:40px;box-shadow:none!important}
html[data-px=p2] body :is(.seg,.vtabs) button.on{box-shadow:inset 0 -4px 0 var(--c-lit,var(--gold))!important}
html[data-px=p2] body .seg button.on.sell{box-shadow:inset 0 -4px 0 var(--red,#f0565d)!important}
html[data-px=p2] body .tfs button{clip-path:none;box-shadow:none!important;border:0!important;min-height:32px}
html[data-px=p2] body .tfs button.on{box-shadow:inset 0 -4px 0 var(--c-lit,var(--gold))!important}

/* ---------- 2) riel izquierdo en horizontal: flotante, angosto y plegable ---------- */
#v3rt{display:none}
html.v3m{--v3l:calc(80px + env(safe-area-inset-left));--v3zl:var(--v3l);--v3pl:var(--v3l)}
html.v3m.v3rc{--v3l:calc(8px + env(safe-area-inset-left));--v3zl:calc(70px + env(safe-area-inset-left));--v3pl:calc(70px + env(safe-area-inset-left))}
html.v3m body.land .bottom{top:var(--v3t);bottom:auto;left:calc(6px + env(safe-area-inset-left));right:auto;width:66px;height:auto;max-height:calc(100% - var(--v3t) - var(--v3bt));padding:5px!important;
 border:1px solid var(--line2,#2b3a4e)!important;border-radius:20px;background:rgba(10,14,20,.56)!important;box-shadow:0 6px 18px rgba(0,0,0,.28);overflow-x:hidden;overflow-y:auto;scrollbar-width:none;overscroll-behavior:contain;
 transition:top .22s cubic-bezier(.2,.8,.2,1),width .2s cubic-bezier(.2,.8,.2,1),border-radius .2s ease}
@supports (background:color-mix(in srgb,red 50%,transparent)){html.v3m body.land .bottom{background:color-mix(in srgb,var(--bg) 58%,transparent)!important}}
html.v3m body.land .bottom::-webkit-scrollbar{display:none}
html.v3m body.land .bottom>.in{display:flex!important;flex-direction:column;align-items:stretch;gap:3px;height:auto;max-width:none!important}
html.v3m #v3rt{position:relative;display:flex;align-items:center;justify-content:center;flex:none;height:34px;border-radius:12px;color:var(--mut);font-size:16px;font-weight:800;line-height:1;cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;touch-action:manipulation;transition:color .15s,transform .15s}
html.v3m #v3rt::after{content:'';position:absolute;inset:-5px -5px 0}
html.v3m #v3rt:active{transform:scale(.92);color:var(--ink)}
html.v3m body.land .bottom .nav{position:relative;flex:none;width:100%;min-height:46px;padding:4px 0 3px!important;gap:2px;border:0!important;border-radius:12px;background:transparent!important;box-shadow:none!important;clip-path:none;
 font-size:9.5px;font-weight:700;letter-spacing:.01em;line-height:1.1;color:var(--ink2,var(--ink));white-space:nowrap;overflow:hidden;text-overflow:clip;animation:v3ein .18s cubic-bezier(.2,.8,.2,1)}
html.v3m body.land .bottom .nav .ic{font-size:20px;line-height:1;opacity:.95}
html.v3m body.land .bottom .nav .ic svg{width:21px;height:21px}
html.v3m body.land .bottom .nav:active{background:rgba(255,255,255,.08)!important;transform:scale(.95)}
html.v3m body.land .bottom .nav.on{box-shadow:inset 3px 0 0 var(--act,var(--gold))!important;color:var(--ink)}
html.v3m body.land .bottom .nav .badge{position:absolute;top:3px;right:5px;min-width:15px;height:15px;line-height:15px;padding:0 3px;border-radius:8px;background:var(--gold);color:#1a1405;font-size:9.5px;font-weight:800}
html.v3m body.land .bottom .nav .badge:empty{display:none}
html.v3m body.land #ageBtn{flex:none;width:100%;min-height:52px;margin:1px 0;padding:4px 2px;border-radius:15px;font-size:11px!important;font-weight:800;line-height:1.1;white-space:normal;letter-spacing:-.01em;overflow-wrap:anywhere;box-shadow:0 3px 10px rgba(0,0,0,.3)}
@keyframes v3ein{from{opacity:0;transform:translateX(-8px)}to{opacity:1;transform:none}}
/* plegado: una burbuja con ☰ y el botón dorado, debajo de la burbuja Personaje */
html.v3m.v3rc body.land .bottom{top:calc(var(--v3t) + 50px);width:58px;padding:4px!important;border-radius:29px}
html.v3m.v3rc body.land .bottom .nav{display:none}
html.v3m.v3rc #v3rt{height:30px}
html.v3m.v3rc body.land #ageBtn{min-height:48px;border-radius:24px;font-size:10.5px!important}
/* lo que se apoya en el riel */
html.v3m body.land .app{left:var(--v3pl)}
html.v3m #mapWrap .zoom{left:var(--v3zl)}
html.v3m #mapWrap .mleg{left:calc(var(--v3zl) + 52px)}
html.v3m #mapWrap .zoom,html.v3m #mapWrap .mleg,html.v3m #v3top{transition:left .2s cubic-bezier(.2,.8,.2,1)}
html.v3m #mapWrap .mmodes>button.on{border-color:var(--act,var(--gold));box-shadow:inset 0 -2px 0 var(--act,var(--gold))}
/* pixel */
html[data-px=p2].v3m body.land .bottom{border:2px solid var(--px-edge)!important;border-radius:0;box-shadow:inset 2px 2px 0 var(--px-hi),inset -2px -2px 0 var(--px-lo),0 3px 0 var(--px-slab,rgba(0,0,0,.4))}
html[data-px=p2].v3m body.land .bottom .nav{font-size:8px;border-radius:0;background-image:none}
html[data-px=p2].v3m body.land .bottom .nav.on{box-shadow:inset 4px 0 0 var(--c-lit,var(--gold))!important}
html[data-px=p2].v3m body.land .bottom .nav .badge{border-radius:0;font-size:8px}
html[data-px=p2].v3m body.land #ageBtn{font-size:8px!important;line-height:1.35;border-radius:0}
html[data-px=p2].v3m #v3rt{border-radius:0;font-family:var(--pxf);font-size:12px}
html[data-px=p2].v3m body.land .bottom,html[data-px=p2].v3m #mapWrap .zoom,html[data-px=p2].v3m #v3top{transition:none}

/* ---------- 3) pantalla completa en horizontal: hojas compactas (la información importante sin desplazarse) ---------- */
html.v3m body.land .sheet h3{margin:0 0 6px;font-size:16px;line-height:1.25}
html.v3m body.land .sheet .item{padding-top:7px;padding-bottom:7px}
html.v3m body.land .sheet .hint{font-size:12px}
html.v3m body.land .sheet .card{margin-bottom:8px}
@media (prefers-reduced-motion:reduce){html.v3m body.land .bottom,html.v3m body.land .bottom .nav,html.v3m #mapWrap .zoom,html.v3m #v3top{transition:none!important;animation:none!important}}

:root{--v4rim:rgba(255,255,255,.2);--v4gb:rgba(16,24,34,.62);--v4gr:radial-gradient(130% 120% at 28% 16%,rgba(255,255,255,.26),rgba(255,255,255,.07) 42%,rgba(0,0,0,.12) 100%);
 --v4sh:inset 0 1px 1px rgba(255,255,255,.34),inset 0 -4px 8px rgba(0,0,0,.22),0 5px 12px rgba(0,0,0,.32);--v4on:var(--act,var(--gold));--v4glow:rgba(242,193,78,.5)}
@supports (background:color-mix(in srgb,red 50%,transparent)){:root{--v4gb:color-mix(in srgb,var(--glass,#0c121a) 62%,transparent);--v4glow:color-mix(in srgb,var(--act,#f2c14e) 50%,transparent)}}
.v4i{width:1.2em;height:1.2em;vertical-align:-.22em;flex:none}
/* ---------- gota de cristal líquido (luz arriba a la izquierda, brillo especular pequeño, sombra suave abajo) ---------- */
.v4d,.v4cc,.v4m,#v4dr .v4dn,html.v3m body.land .bottom>.in>.nav,html.v3m body.land .shx button,html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button,html.v3m .abx>.btn:not(.gold),html.v3m .abt{
 position:relative;border:1px solid var(--v4rim)!important;background:var(--v4gr),var(--v4gb)!important;box-shadow:var(--v4sh)!important;color:var(--ink)}
.v4d::before,.v4cc::before,html.v3m body.land .bottom>.in>.nav::before{content:'';position:absolute;left:19%;top:8%;width:30%;height:17%;border-radius:50%;background:radial-gradient(closest-side,rgba(255,255,255,.72),rgba(255,255,255,0));pointer-events:none}
html:not(.v4lt) .v4d,html.v3m:not(.v4lt) body.land .bottom>.in>.nav{-webkit-backdrop-filter:blur(9px) saturate(1.5);backdrop-filter:blur(9px) saturate(1.5)}

/* ---------- C) riel: gotas por categoría ---------- */
.v4cat{display:none}
html.v3m:not(.v3rc) body.land .bottom{width:72px;left:calc(4px + env(safe-area-inset-left));padding:4px!important;background:transparent!important;border-color:transparent!important;box-shadow:none!important}
html.v3m body.land .bottom{z-index:22}
html.v3m body.land .bottom>.in{gap:4px!important;align-items:center!important}
html.v3m body.land .bottom>.in>*{order:8}
html.v3m body.land .bottom>.in>#v3rt{order:0;align-self:stretch}
html.v3m body.land .bottom>.in>.v4cat[data-c=tu]{order:1}html.v3m body.land .bottom>.in>#nAct{order:2}html.v3m body.land .bottom>.in>#nCar{order:3}
html.v3m body.land .bottom>.in>.v4cat[data-c=mu]{order:4}html.v3m body.land .bottom>.in>#nNat{order:5}
html.v3m body.land .bottom>.in>.v4cat[data-c=ju]{order:6}html.v3m body.land .bottom>.in>#nMore{order:7}html.v3m body.land .bottom>.in>#ageBtn{order:9}
html.v3m:not(.v3rc) body.land .bottom>.in>.v4cat{display:block;align-self:stretch;margin:3px 0 -2px;font-size:8px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;text-align:center;color:var(--ink);opacity:.75;text-shadow:0 1px 3px rgba(0,0,0,.85);pointer-events:none;white-space:nowrap;overflow:hidden}
html.v3m body.land .bottom>.in>.nav{width:56px!important;height:56px;min-height:56px!important;flex:none!important;padding:3px 2px 0!important;border-radius:50%!important;display:flex!important;flex-direction:column;align-items:center;justify-content:center;gap:1px!important;
 font-size:8.5px!important;line-height:1.05!important;overflow:visible!important;animation:none!important;transition:transform .24s cubic-bezier(.3,1.4,.5,1),box-shadow .2s ease,border-color .2s ease}
html.v3m body.land .bottom>.in>.nav .ic{font-size:19px!important}
html.v3m body.land .bottom>.in>.nav .badge{top:-3px!important;right:-4px!important}
html.v3m body.land .bottom>.in>.nav:active{transform:scale(.92)}
html.v3m body.land .bottom>.in>.nav.on{border-color:var(--v4on)!important;color:var(--ink)!important;transform:scale(1.08);z-index:1;
 box-shadow:0 0 0 1.5px var(--v4on),0 0 14px var(--v4glow),inset 0 1px 1px rgba(255,255,255,.42),0 5px 12px rgba(0,0,0,.32)!important}
html.v3m:not(.v3rc) body.land .bottom>.in>#ageBtn{width:62px!important;margin-top:6px!important;box-shadow:inset 0 1px 1px rgba(255,255,255,.5),inset 0 -4px 8px rgba(0,0,0,.18),0 5px 12px rgba(0,0,0,.35)!important}
/* submenús que brotan del botón tocado */
#v4dr{position:fixed;z-index:23;display:flex;align-items:center;height:62px;pointer-events:none}
#v4dr[hidden]{display:none}
#v4dr .v4dn{flex:none;width:16px;height:24px;margin-right:-6px;border-radius:50%;opacity:0;transform:scale(.3);transition:opacity .16s ease,transform .26s cubic-bezier(.3,1.4,.5,1)}
#v4dr .v4dt{display:flex;align-items:center;gap:6px;padding:5px 8px 5px 6px;border-radius:31px;overflow-x:auto;overflow-y:hidden;scrollbar-width:none;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;touch-action:pan-x;pointer-events:auto;background:rgba(10,14,20,.25)}
#v4dr .v4dt::-webkit-scrollbar{display:none}
.v4d{flex:none;width:50px;height:50px;border-radius:50%!important;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;padding:2px 3px 0;font-size:8.5px;font-weight:700;line-height:1.05;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent;
 opacity:0;transform:translateX(calc(var(--n,0) * -56px)) scale(.35);transition:transform .34s cubic-bezier(.3,1.35,.5,1) calc(var(--n,0) * 28ms),opacity .18s ease calc(var(--n,0) * 28ms)}
.v4d i{font-style:normal;font-size:18px;line-height:1}.v4d span{max-width:46px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#v4dr.v4o .v4dn{opacity:1;transform:none}#v4dr.v4o .v4d{opacity:1;transform:none}
.v4d:active{transform:scale(.92)!important}
.v4d.on{border-color:var(--v4on)!important;box-shadow:0 0 0 1.5px var(--v4on),0 0 10px var(--v4glow),var(--v4sh)!important}
.sect.v4gh{display:flex;align-items:center;gap:6px}.sect.v4gh.v4fl{animation:v4fl .9s ease}
@keyframes v4fl{0%,100%{color:inherit}30%{color:var(--v4on)}}

/* ---------- D) barra de submenús: cristal compacto, atrás con historial, métricas con su tiempo, filas que se arrastran ---------- */
html.v3m body.land .shx{justify-content:flex-start;height:34px;gap:5px;margin:-4px 0 6px}
html.v3m body.land .shx button{height:32px;padding:0 12px;border-radius:16px!important;font-size:12px;max-width:40%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
html.v3m body.land .shx .hm{margin-left:auto}html.v3m body.land .shx .v4ck{opacity:.8;font-size:11px;max-width:30%}
.shx .bk,.shx .v4ck{max-width:44%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt){gap:5px;border-bottom:0!important;padding:3px 2px 6px;margin:2px 0 4px}
html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button{flex:0 0 auto!important;height:34px;min-height:34px!important;padding:0 13px!important;border-radius:17px!important;color:var(--mut)!important;font-size:12.5px}
html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button::after{display:none}
html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button.on{color:var(--ink)!important;border-color:var(--v4on)!important;box-shadow:0 0 0 1px var(--v4on),0 0 10px var(--v4glow),inset 0 1px 1px rgba(255,255,255,.36)!important}
html.v3m .abt{border-color:var(--gold)!important;color:var(--gold)}
html.v3m .abx{scroll-behavior:auto;scroll-snap-type:none}
html.v3m .abx>.btn{border-radius:22px!important}
.v4mt{display:flex;gap:6px;overflow-x:auto;overflow-y:hidden;scrollbar-width:none;margin:2px 0 8px;padding:2px 1px 5px;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;touch-action:pan-x}
.v4mt::-webkit-scrollbar{display:none}
.v4m{flex:none;display:flex;flex-direction:column;min-width:86px;padding:5px 11px;border-radius:14px!important;line-height:1.2}
.v4m small{font-size:10.5px;color:var(--mut);white-space:nowrap}.v4m b{font-size:14px;white-space:nowrap}.v4m em{font-style:normal;font-size:10px;color:var(--mut);white-space:nowrap}
.v4m b.u{color:var(--teal,#3ccf8e)}.v4m b.d{color:var(--red,#f0565d)}
.app #v4np{margin:0 0 8px}
/* barra fina para desplazar una fila larga (se puede agarrar y arrastrar) */
.v4th{position:relative;height:14px;margin:-9px 4px 2px;touch-action:none;cursor:grab;-webkit-tap-highlight-color:transparent}
.v4th[hidden]{display:none}
.v4th>i{position:absolute;left:0;top:5px;height:3px;min-width:24px;border-radius:3px;background:var(--mut,#7b8794);opacity:.4;transition:opacity .15s ease,height .15s ease,top .15s ease}
.v4th:hover>i,.v4th.v4g>i{opacity:.85;height:5px;top:4px}

/* ---------- A) ficha de ciudad y de provincia sin desplazarse (horizontal) ---------- */
.v4cs[hidden]{display:none!important}
html.v3m body.land #sheetIn.v4pl .plh{gap:8px}
html.v3m body.land #sheetIn.v4pl .plh h3{font-size:17px;margin:0}
html.v3m body.land #sheetIn.v4pl .plh .pln small{font-size:11.5px}
html.v3m body.land #sheetIn.v4pl .plh>img{width:22px;height:auto}
html.v3m body.land #sheetIn.v4pl .plx{padding:5px 9px;font-size:12px}
html.v3m body.land #sheetIn.v4pl>.mpt{margin:3px 0 0;font-size:11px}
html.v3m body.land #sheetIn.v4pl .pltabs{margin:4px 0 4px}
html.v3m body.land #sheetIn.v4pl .plg{grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:5px;margin:4px 0 6px}
html.v3m body.land #sheetIn.v4pl .plt{padding:4px 8px}html.v3m body.land #sheetIn.v4pl .plt b{font-size:14px}
html.v3m body.land #sheetIn.v4pl .plcy{padding:7px 9px;margin-bottom:6px}
html.v3m body.land #sheetIn.v4pl .plcy h4{font-size:15px}
html.v3m body.land #sheetIn.v4pl .plcy .plg{margin:5px 0 0}
html.v3m body.land #sheetIn.v4pl .sect.v4as{display:none}
html.v3m body.land #sheetIn.v4pl .v4ct{margin:2px 0 6px}
html.v3m body.land #sheetIn.v4pl .pla.v4ab{position:sticky;bottom:0;z-index:5;margin:8px -4px 0;padding:6px 5px;border-radius:16px;grid-template-columns:repeat(auto-fit,minmax(70px,1fr));
 background:var(--glass,#0c121a);border:1px solid var(--line2,#2b3a4e);box-shadow:0 -6px 16px rgba(0,0,0,.28)}
html.v3m body.land #sheetIn.v4pl .pla.v4ab button{min-height:50px;padding:5px 2px 4px}
/* ---------- B) botón de envíos ---------- */
.mmodes button.lgt{display:none!important}
#selInfo .plfx .btn.v4lgb{flex:0 0 46px;min-width:46px;padding:0;display:flex;align-items:center;justify-content:center;font-size:17px}
[data-v4lg].on{color:var(--teal,#3ccf8e)!important;border-color:var(--teal,#3ccf8e)!important}
[data-v4lg]:not(.on){color:var(--mut)}
/* ---------- E) burbuja del mapa por tipo de mapa ---------- */
.mpop .v4mc{display:flex;gap:4px;margin:7px 0 3px}
.v4cc{flex:1 1 0;min-width:0;height:32px;border-radius:16px!important;display:flex;align-items:center;justify-content:center;gap:4px;padding:0 6px;color:var(--mut);font-size:11px;font-weight:700;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:flex-grow .2s ease}
.v4cc i{font-style:normal;font-size:15px;line-height:1}.v4cc span{display:none}
.v4cc.on{flex:2.6 1 0;color:var(--ink);border-color:var(--v4on)!important;box-shadow:0 0 0 1px var(--v4on),0 0 8px var(--v4glow),var(--v4sh)!important}
.v4cc.on span{display:inline;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mpop .v4mm{display:flex;flex-wrap:wrap;gap:3px 10px;margin:4px 0 2px;font-size:12px}
.v4mm b{font-weight:800}.v4mm small{color:var(--mut)}.v4mm em{font-style:normal;color:var(--mut);font-size:10.5px}
.mpop .mpa.v4m6{grid-template-columns:repeat(3,1fr)}
/* ---------- pixel y movimiento reducido ---------- */
html[data-px=p2] :is(.v4d,.v4cc,.v4m,#v4dr .v4dn,#v4dr .v4dt),html[data-px=p2].v3m body.land .bottom>.in>.nav,html[data-px=p2].v3m body.land .shx button{border-radius:0!important;background:var(--card2)!important;border:2px solid var(--px-edge)!important;
 box-shadow:inset 2px 2px 0 var(--px-hi),inset -2px -2px 0 var(--px-lo)!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
html[data-px=p2] :is(.v4d,.v4cc)::before,html[data-px=p2].v3m body.land .bottom>.in>.nav::before{display:none}
html[data-px=p2].v3m body.land .bottom>.in>.nav.on,html[data-px=p2] :is(.v4d,.v4cc).on{box-shadow:inset 0 -4px 0 var(--c-lit,var(--gold)),inset 2px 2px 0 var(--px-hi)!important;transform:none}
html[data-px=p2].v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button{border-radius:0!important;border:0!important;background:none!important;box-shadow:none!important}
html[data-px=p2].v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button.on{box-shadow:inset 0 -4px 0 var(--c-lit,var(--gold))!important}
html[data-px=p2] #v4dr .v4d,html[data-px=p2] #v4dr .v4dn{transition:opacity 80ms steps(2,end),transform 80ms steps(2,end)}
@media (prefers-reduced-motion:reduce){.v4d,#v4dr .v4dn,.v4cc,html.v3m body.land .bottom>.in>.nav{transition:none!important}.sect.v4gh.v4fl{animation:none}}

:root{--v5rim:rgba(255,255,255,.26);--v5gb:rgba(14,20,30,.42);
 --v5gr:radial-gradient(120% 110% at 30% 14%,rgba(255,255,255,.3),rgba(255,255,255,.08) 40%,rgba(255,255,255,0) 62%,rgba(0,0,0,.16) 100%);
 --v5sh:inset 0 1px 1px rgba(255,255,255,.4),inset 0 -5px 9px rgba(0,0,0,.2),inset 0 0 0 1px rgba(255,255,255,.05),0 6px 14px rgba(0,0,0,.28)}
@supports (background:color-mix(in srgb,red 50%,transparent)){:root{--v5gb:color-mix(in srgb,var(--glass,#0c121a) 42%,transparent)}}
/* botones del riel: cristal más claro y más transparente */
html.v3m body.land .bottom>.in>.nav{border:1px solid var(--v5rim)!important;background:var(--v5gr),var(--v5gb)!important;box-shadow:var(--v5sh)!important;
 transition:transform .18s cubic-bezier(.3,1.5,.5,1),box-shadow .16s ease,border-color .16s ease,background-color .16s ease}
/* brillo especular más nítido (reflejo de la gota) */
html.v3m body.land .bottom>.in>.nav::before{left:20%;top:9%;width:34%;height:19%;background:radial-gradient(closest-side,rgba(255,255,255,.85),rgba(255,255,255,0))}
/* reflejo inferior suave (refracción) */
html.v3m body.land .bottom>.in>.nav::after{content:'';position:absolute;left:30%;bottom:7%;width:40%;height:12%;border-radius:50%;background:radial-gradient(closest-side,rgba(255,255,255,.22),rgba(255,255,255,0));pointer-events:none}
/* activo: brilla un poco más y crece con rebote */
html.v3m body.land .bottom>.in>.nav.on{transform:scale(1.1)}
/* submenús que brotan: más rápidos y más transparentes */
.v4d{background:var(--v5gr),var(--v5gb)!important;border:1px solid var(--v5rim)!important;box-shadow:var(--v5sh)!important;
 transition:transform .24s cubic-bezier(.3,1.5,.5,1) calc(var(--n,0) * 18ms),opacity .14s ease calc(var(--n,0) * 18ms)}
.v4d::before{left:20%;top:9%;width:32%;height:18%;background:radial-gradient(closest-side,rgba(255,255,255,.8),rgba(255,255,255,0))}
#v4dr .v4dn{background:var(--v5gb);border:1px solid var(--v5rim);transition:opacity .12s ease,transform .18s cubic-bezier(.3,1.5,.5,1)}
#v4dr.v4o .v4d,#v4dr.v4o .v4dn{opacity:1}
html.v3m body.land .bottom>.in>.nav:active,.v4d:active{transform:scale(.9)!important}
/* burbujas superiores (reloj, Personaje, País, noticias): mismo cristal que el riel */
html.v3m #v3top>.v3bb,html.v3m #v3top #tick.v3dot{border:1px solid var(--v5rim)!important;background:var(--v5gr),var(--v5gb)!important;box-shadow:var(--v5sh)!important;transition:transform .18s cubic-bezier(.3,1.5,.5,1),box-shadow .16s ease}
html.v3m #v3top>.v3bb:active{transform:scale(.92)}
/* barra de submenús (.shx): una cápsula de cristal que contiene las opciones; «‹ Atrás» con tinte propio */
html.v3m body.land .shx{position:relative;padding:3px;border-radius:20px;background:var(--v5gb);border:1px solid var(--v5rim);box-shadow:inset 0 1px 1px rgba(255,255,255,.18),0 3px 8px rgba(0,0,0,.2);width:max-content;max-width:100%;margin:-2px 0 8px}
html.v3m body.land .shx button{border:1px solid var(--v5rim)!important;background:var(--v5gr),var(--v5gb)!important;box-shadow:var(--v5sh)!important;transition:transform .18s cubic-bezier(.3,1.5,.5,1),box-shadow .16s ease,border-color .16s ease}
html.v3m body.land .shx button:active{transform:scale(.93)}
html.v3m body.land .shx button.on,html.v3m body.land .shx button[aria-current=true]{border-color:var(--v4on)!important;box-shadow:0 0 0 1px var(--v4on),0 0 10px var(--v4glow),var(--v5sh)!important;transform:scale(1.04)}
html.v3m body.land .shx .bk{background:linear-gradient(180deg,rgba(255,255,255,.16),rgba(255,255,255,.02)),var(--v5gb)!important;color:var(--mut,#b9c4d2)!important}
/* métricas de la barra (.v4mt): mismas gotas, más transparentes */
html.v3m body.land .v4m{background:var(--v5gr),var(--v5gb)!important;border:1px solid var(--v5rim)!important;box-shadow:var(--v5sh)!important;transition:transform .18s cubic-bezier(.3,1.5,.5,1)}
html.v3m body.land .v4m:active{transform:scale(.96)}
/* pestañas de las hojas (.ntabs, .mkt, .nwt): gotas pequeñas; la activa brilla */
html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button{border:1px solid var(--v5rim)!important;background:var(--v5gr),var(--v5gb)!important;box-shadow:var(--v5sh)!important;transition:transform .18s cubic-bezier(.3,1.5,.5,1),box-shadow .16s ease,border-color .16s ease}
html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button:active{transform:scale(.94)}
html.v3m body.land :is(.sheet,.app) :is(.ntabs,.mkt,.nwt) button.on{border-color:var(--v4on)!important;box-shadow:0 0 0 1px var(--v4on),0 0 10px var(--v4glow),var(--v5sh)!important}
/* con desenfoque (fuera del modo ligero): ligero y sin costo en el iPhone */
html:not(.v4lt) .v4d,html.v3m:not(.v4lt) body.land .bottom>.in>.nav{-webkit-backdrop-filter:blur(6px) saturate(1.6);backdrop-filter:blur(6px) saturate(1.6)}
/* modo ligero (Toshiba, mapa en Canvas 2D): sin desenfoque ni reflejos extra */
html.v4lt .v4d,html.v4lt body.land .bottom>.in>.nav{-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
html.v4lt body.land .bottom>.in>.nav::after{display:none}
@media (prefers-reduced-motion:reduce){html.v3m body.land .bottom>.in>.nav,.v4d,#v4dr .v4dn{transition:none!important}}

/* ---------- 6) gotas más vivas: matiz del tema, más brillo, reflejo marcado ---------- */
:root{--v5rim:rgba(255,255,255,.38);--v5gb:rgba(18,40,70,.5);
 --v5gr:radial-gradient(120% 110% at 30% 10%,rgba(255,255,255,.46),rgba(255,255,255,.13) 36%,rgba(255,255,255,0) 58%,rgba(0,0,0,.14) 100%),linear-gradient(165deg,rgba(110,190,255,.22),rgba(110,190,255,0) 60%);
 --v5sh:inset 0 1.5px 1px rgba(255,255,255,.62),inset 0 -6px 10px rgba(0,0,0,.2),inset 0 0 0 1px rgba(255,255,255,.07),0 6px 14px rgba(0,0,0,.28);
 --v6rim:rgba(255,255,255,.26);--v6bar:rgba(12,22,36,.66)}
@supports (background:color-mix(in srgb,red 50%,transparent)){:root{
 --v5gb:color-mix(in srgb,var(--act,#f2c14e) 16%,var(--glass,#0c121a) 36%);
 --v5rim:color-mix(in srgb,var(--act,#f2c14e) 38%,rgba(255,255,255,.62));
 --v5gr:radial-gradient(120% 110% at 30% 10%,rgba(255,255,255,.46),rgba(255,255,255,.13) 36%,rgba(255,255,255,0) 58%,rgba(0,0,0,.14) 100%),linear-gradient(165deg,color-mix(in srgb,var(--act,#f2c14e) 34%,transparent),transparent 62%);
 --v4glow:color-mix(in srgb,var(--act,#f2c14e) 62%,transparent);
 --v6rim:color-mix(in srgb,var(--act,#f2c14e) 26%,rgba(255,255,255,.34));
 --v6bar:color-mix(in srgb,var(--act,#f2c14e) 8%,var(--glass,#0c121a) 64%)}}
.v4d::before,html.v3m #v3top>.v3bb::before{background:radial-gradient(closest-side,rgba(255,255,255,.98),rgba(255,255,255,0))!important}
.v4d::before{left:18%;top:7%;width:38%;height:22%}
html.v3m #v3top>.v3bb{position:relative}
html.v3m:not(.v4lt) #v3top>.v3bb::before{content:'';position:absolute;left:10%;top:6%;width:26%;height:30%;border-radius:50%;pointer-events:none;opacity:.55}
html.v4lt{--v5gr:linear-gradient(180deg,rgba(255,255,255,.2),rgba(255,255,255,0) 55%);--v5sh:inset 0 1px 0 rgba(255,255,255,.4),0 3px 8px rgba(0,0,0,.3)}
html.v4lt .v4d::before{display:none}

/* ---------- 2) riel unido: una barra de cristal común ---------- */
#v5per{display:none}
html.v3m{--v3l:calc(110px + env(safe-area-inset-left));--v3zl:var(--v3l);--v3pl:var(--v3l)}
html.v3m.v3rc{--v3l:calc(110px + env(safe-area-inset-left));--v3zl:calc(8px + env(safe-area-inset-left));--v3pl:var(--v3l)}
html.v3m body.land .bottom.bottom{left:calc(6px + env(safe-area-inset-left))!important;top:var(--v3t)!important;padding:4px!important;border:1px solid var(--v6rim)!important;background:var(--v6bar)!important;
 box-shadow:inset 0 1px 0 rgba(255,255,255,.22),inset 0 0 0 1px rgba(255,255,255,.04),0 8px 20px rgba(0,0,0,.32)!important;border-radius:22px!important}
html.v3m:not(.v3rc) body.land .bottom{width:98px!important}
html.v3m body.land .bottom>.in{display:grid!important;grid-template-columns:1fr 1fr;gap:2px!important;align-items:stretch!important}
html.v3m body.land .bottom>.in>:is(#v3rt,#v5per,#ageBtn){grid-column:1/-1}
html.v3m body.land .bottom>.in>.v4cat{display:none!important}
html.v3m body.land .bottom>.in>#v5per{order:8}
html.v3m #v3rt{height:24px;border-radius:10px}
/* botones del riel: celdas planas dentro de la barra (sin gota propia ni desenfoque) */
html.v3m body.land .bottom>.in>.nav{width:auto!important;height:44px;min-height:44px!important;padding:3px 1px 1px!important;border:0!important;border-radius:12px!important;
 background:transparent!important;box-shadow:none!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;transform:none;font-size:8.5px!important;gap:1px!important;overflow:hidden!important}
html.v3m body.land .bottom>.in>.nav::before,html.v3m body.land .bottom>.in>.nav::after{display:none!important}
html.v3m body.land .bottom>.in>.nav .ic{font-size:18px!important}
html.v3m body.land .bottom>.in>.nav .badge{top:1px!important;right:2px!important}
html.v3m body.land .bottom>.in>.nav:active{background:rgba(255,255,255,.1)!important;transform:scale(.95)!important}
html.v3m body.land .bottom>.in>.nav.on{transform:none!important;color:var(--ink)!important;background:rgba(242,193,78,.2)!important;box-shadow:inset 0 0 0 1px var(--v4on),inset 0 1px 0 rgba(255,255,255,.3)!important}
@supports (background:color-mix(in srgb,red 50%,transparent)){html.v3m body.land .bottom>.in>.nav.on,html.v3m body.land #v5per>button.on{background:color-mix(in srgb,var(--act,#f2c14e) 24%,transparent)!important}}
/* 4) periodos: rejilla de 2×3 entre separadores finos */
html.v3m:not(.v3rc) body.land #v5per{display:grid;grid-template-columns:1fr 1fr;gap:2px;margin:3px 0;padding:4px 0;border-top:1px solid rgba(255,255,255,.14);border-bottom:1px solid rgba(255,255,255,.14)}
html.v3m body.land #v5per>button{height:38px;min-height:38px;margin:0;padding:1px 0 0;border:0;border-radius:10px;background:rgba(255,255,255,.05);color:var(--ink2,var(--ink));display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;
 font:700 8.5px/1.05 system-ui,-apple-system,'Segoe UI',sans-serif;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none;overflow:hidden;transition:background-color .14s ease,transform .14s ease}
html.v3m body.land #v5per>button b{font-size:14px;line-height:1;font-weight:800}
html.v3m body.land #v5per>button small{font-size:8.5px;max-width:44px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.85}
html.v3m body.land #v5per>button:active{transform:scale(.94)}
html.v3m body.land #v5per>button.on{color:var(--ink);background:rgba(242,193,78,.22);box-shadow:inset 0 0 0 1px var(--v4on),0 0 8px var(--v4glow)}
html.v3m body.land #v5per>button.on small{opacity:1}
/* botón de avanzar integrado al pie de la barra (siempre visible: pegado abajo si la barra se desplaza) */
html.v3m:not(.v3rc) body.land .bottom>.in>#ageBtn{width:auto!important;min-height:46px;margin:0!important;border-radius:16px;position:sticky;bottom:0;z-index:1;
 box-shadow:inset 0 1px 1px rgba(255,255,255,.55),inset 0 -4px 8px rgba(0,0,0,.18),0 2px 8px rgba(0,0,0,.3)!important}
/* pantallas bajas (Safari con barras): todo cabe sin desplazarse */
@media (max-height:350px){html.v3m body.land .bottom>.in>.nav{height:40px;min-height:40px!important}html.v3m body.land #v5per>button{height:34px;min-height:34px}html.v3m #v3rt{height:20px}html.v3m:not(.v3rc) body.land .bottom>.in>#ageBtn{min-height:42px}}
@media (min-height:400px){html.v3m body.land #v5per>button{height:44px;min-height:44px}}
/* ---------- 3) plegado: solo el botón de avanzar (donde empezaba el riel) y una pestaña para abrir ---------- */
html.v3m.v3rc body.land .bottom.bottom{width:auto!important;max-width:calc(var(--v3l) - 10px - env(safe-area-inset-left));border-radius:26px!important}
html.v3m.v3rc body.land .bottom>.in{grid-template-columns:62px 24px}
html.v3m.v3rc body.land .bottom>.in>:is(.nav,#v5per){display:none!important}
html.v3m.v3rc body.land .bottom>.in>#ageBtn{grid-column:1;order:1;width:62px!important;min-height:46px;margin:0!important;border-radius:22px;font-size:10.5px!important}
html.v3m.v3rc body.land .bottom>.in>#v3rt{grid-column:2;order:2;height:auto;align-self:stretch;font-size:0;border-radius:12px;background:rgba(255,255,255,.06)}
html.v3m.v3rc body.land .bottom>.in>#v3rt::before{content:'›';font-size:20px;font-weight:800;line-height:1;color:var(--ink)}
html.v3m.v3rc #v3rt::after{inset:-6px -10px -6px -4px}
/* pixel */
html[data-px=p2].v3m body.land .bottom.bottom{border-radius:0!important;border:2px solid var(--px-edge)!important;background:var(--card)!important;box-shadow:inset 2px 2px 0 var(--px-hi),inset -2px -2px 0 var(--px-lo),0 3px 0 var(--px-slab,rgba(0,0,0,.4))!important}
html[data-px=p2].v3m body.land .bottom>.in>.nav,html[data-px=p2].v3m body.land #v5per>button,html[data-px=p2].v3m body.land .bottom>.in>#ageBtn{border-radius:0!important}
html[data-px=p2].v3m body.land .bottom>.in>.nav.on,html[data-px=p2].v3m body.land #v5per>button.on{box-shadow:inset 0 -4px 0 var(--c-lit,var(--gold))!important;background:var(--card2)!important}
html[data-px=p2].v3m body.land #v5per>button{font-family:var(--pxf);font-size:7px;transition:none}
/* modo ligero: barra opaca y sin brillos */
html.v4lt.v3m body.land .bottom.bottom{background:var(--glass,#0c121a)!important;box-shadow:0 3px 10px rgba(0,0,0,.35)!important}
html.v4lt.v3m body.land #v5per>button.on{box-shadow:inset 0 0 0 1px var(--v4on)}
@media (prefers-reduced-motion:reduce){html.v3m body.land #v5per>button{transition:none}}

/* ---------- 5) medidas: nada se encima ---------- */
html.v3m #v3top{min-width:0}
html.v3m body>.mapcard{max-width:calc(100vw - var(--v3l) - var(--v3r) - 60px)}

/* ---------- 1) portada «Facetas» ---------- */
#cover.cv-facetas{--cvf0:#0794e4;--cvf1:#0a86d6;--cvfk:#0a6fc2;background:linear-gradient(160deg,var(--cvf0),var(--cvf1));color:#fff}
.cv-facetas #cvC{display:none}
.cv-fac{position:absolute;inset:0;width:100%;height:100%;display:block;pointer-events:none}
.cv-fac g{animation:cvFa 28s ease-in-out infinite alternate;transform-origin:50% 50%}
@keyframes cvFa{from{transform:translate(-6px,-4px) scale(1.04)}to{transform:translate(6px,4px) scale(1.05)}}
.cv-facetas .cv-shade{background:linear-gradient(180deg,rgba(0,40,96,0) 0%,rgba(0,40,96,0) 55%,rgba(0,40,96,.38) 100%)}
.cv-facetas .cv-logo{background:none;-webkit-background-clip:border-box;background-clip:border-box;color:#fff;-webkit-text-fill-color:#fff;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;font-weight:900;letter-spacing:.05em;padding-left:.05em;
 font-size:clamp(44px,13vw,92px);filter:drop-shadow(0 4px 0 rgba(0,52,112,.26))}
.cv-facetas .cv-glb{stroke:#fff;stroke-width:8;filter:none}
.cv-facetas .cv-tag{color:#eef8ff;font-weight:600;text-shadow:0 1px 2px rgba(0,50,110,.45)}
.cv-facetas .cv-b{background:rgba(255,255,255,.16);border-color:rgba(255,255,255,.55);color:#fff}
.cv-facetas .cv-b.gold,.cv-facetas .cv-cont{background:#fff;border-color:#fff;color:var(--cvfk);box-shadow:0 6px 18px rgba(0,50,110,.3)}
.cv-facetas .cv-fact{background:rgba(0,56,120,.42);border-color:rgba(255,255,255,.4);color:#fff}
.cv-facetas .cv-sl,.cv-facetas .cv-foot,.cv-facetas .cv-lang .f{color:#e2f4ff}
.cv-facetas .cv-lang select{background:rgba(0,56,120,.4);border-color:rgba(255,255,255,.5);color:#fff}
.cv-facetas .cv-chips button{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.45);color:#fff}
.cv-facetas .cv-chips button.on{background:#fff;border-color:#fff;color:var(--cvfk);box-shadow:none}
.cv-facetas .cv-cr{background:rgba(4,58,120,.96)}.cv-facetas .cv-cr b{color:#bfeaff}
html.v4lt .cv-fac g{animation:none}
@media (prefers-reduced-motion:reduce){.cv-fac g{animation:none}}

/* ---------- 1) elegir vida ---------- */
.modal.v5ng{padding:10px 14px 0}
.v5ng .v5h{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:2px}
.v5ng .v5h>h2{margin:0;flex:1 1 auto;font-size:18px;line-height:1.2}
.v5ng .v5ht{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.v5ng .v5ht>div{margin:0!important}.v5ng .v5ht select{width:auto;padding:5px 8px;font-size:13px}.v5ng .v5ht label.f{display:none}
.v5ng #sCv{width:auto;margin:0;padding:6px 10px;font-size:12.5px}
.v5ng>p.src{margin:2px 0 6px;font-size:12px}
.v5ng .v5c{display:flex;gap:6px;margin:4px 0 6px}.v5ng .v5c>.opt{flex:1;margin:0;padding:8px 10px;font-size:13.5px}
.v5ng .sect{position:static;margin:6px 0 4px;font-size:11px}
.v5ng .v5g{display:grid;gap:4px 14px}
.v5ng .v5a .row2{gap:6px}
.v5ng label.f{margin:4px 0 2px;font-size:11.5px}
.v5ng .v5a input,.v5ng .v5a select{padding:7px 9px;min-height:36px}
.v5ng .modes.lvls,.v5ng .modes.gms{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.v5ng .modes.lvls .lv,.v5ng .modes.gms .mode{margin:0;padding:7px 4px;min-height:40px;text-align:center;border-radius:11px}
.v5ng .modes.lvls .lv b,.v5ng .modes.gms .mode b{font-size:13.5px;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v5ng .modes.lvls .lv span,.v5ng .modes.gms .mode span{display:none}
.v5ng .v5ds{font-size:11.5px;line-height:1.3;color:var(--mut);margin:4px 1px 2px;min-height:2.6em;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.v5ng #v20lv>.sect:first-child{display:none}.v5ng #v20mo{display:none}
.v5ng #v20pz{margin:4px 0 0;padding:5px 8px;font-size:12px}
.v5ng details.v5mo{margin:8px 0 0;border:1px dashed var(--line);border-radius:10px;padding:5px 10px}
.v5ng details.v5mo>summary{cursor:pointer;font-weight:700;font-size:13.5px;padding:3px 0;list-style-position:inside}
.v5ng details.v5mo>summary small{color:var(--mut);font-weight:600;font-size:11.5px}
.v5ng details.v5mo .modes{gap:6px}.v5ng details.v5mo .mode{padding:7px 10px}.v5ng details.v5mo .mode span{font-size:11.5px}
.v5ng .v5ft{position:sticky;bottom:0;z-index:2;display:flex;align-items:center;gap:10px;margin:8px -14px 0;padding:8px 14px calc(10px + env(safe-area-inset-bottom));background:var(--card);border-top:1px solid var(--line);box-shadow:0 -6px 12px rgba(0,0,0,.18)}
.v5ng .v5ft .v5sum{flex:1 1 auto;min-width:0;font-size:12px;color:var(--mut);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v5ng .v5ft #sGo{width:auto!important;flex:0 0 auto;margin:0!important;padding:11px 22px!important}
@media (max-width:520px){.v5ng .v5ft{flex-wrap:wrap}.v5ng .v5ft .v5sum{flex-basis:100%}.v5ng .v5ft #sGo{flex:1 1 auto}}
@media (orientation:landscape) and (min-width:600px){
 html body .modal.v5ng{width:min(calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)),860px)!important;left:50%!important;top:50%!important;
  max-height:calc(100vh - 12px)!important;max-height:calc(100dvh - 12px)!important}
 .v5ng .v5g{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
 .v5ng>p.src{display:none}}
@media (orientation:landscape) and (max-height:430px){.v5ng .sect{margin:4px 0 3px}.v5ng label.f{margin:2px 0 1px}.v5ng .v5a input,.v5ng .v5a select{padding:5px 8px;min-height:32px}.v5ng .v5ds{min-height:0}}

/* ---------- 2) riel: botones juntos, barra continua y separada de los bordes ---------- */
html.v3m body.land .bottom.bottom{left:calc(10px + env(safe-area-inset-left))!important;top:calc(var(--v3t) + 4px)!important;max-height:calc(100% - var(--v3t) - var(--v3bt) - 8px)!important;padding:5px!important;border-radius:24px!important;
 background:linear-gradient(180deg,rgba(255,255,255,.11),rgba(255,255,255,.02) 22%,rgba(255,255,255,0) 70%,rgba(0,0,0,.14)),var(--v6bar)!important}
html.v3m:not(.v3rc) body.land .bottom{width:94px!important}
html.v3m body.land .bottom>.in{gap:2px!important;grid-auto-rows:auto!important;align-content:start!important;height:auto!important}
html.v3m body.land .bottom>.in>.nav{height:42px;min-height:42px!important;margin:0!important;border-radius:13px!important}
html.v3m body.land .bottom>.in>.nav:not(.on):hover{background:rgba(255,255,255,.06)!important}
html.v3m #v3rt{height:20px;margin:0 0 1px}
html.v3m:not(.v3rc) body.land #v5per{margin:3px 2px!important;padding:4px 0!important;gap:2px!important;border-color:rgba(255,255,255,.1)!important}
html.v3m body.land #v5per>button{height:34px;min-height:34px}
@media (min-height:400px){html.v3m body.land #v5per>button{height:38px;min-height:38px}}
html.v3m:not(.v3rc) body.land .bottom>.in>#ageBtn{min-height:44px;margin-top:2px!important}
@media (max-height:350px){html.v3m body.land .bottom>.in>.nav{height:38px;min-height:38px!important}html.v3m body.land #v5per>button{height:31px;min-height:31px}}

/* ---------- 3) portada «Facetas» viva ---------- */
#cover.cv-facetas{overflow:hidden}
.cv-fac.v5qf{inset:-5%;width:110%;height:110%;will-change:transform;backface-visibility:hidden}
.cv-fac.v5qf g{animation:none!important}
.v5qf1{animation:v5qF1 38s ease-in-out infinite alternate}
.v5qf2{animation:v5qF2 29s ease-in-out infinite alternate}
.v5qf3{animation:v5qF3 23s ease-in-out infinite alternate}
@keyframes v5qF1{from{transform:translate3d(-10px,-6px,0) scale(1.01)}to{transform:translate3d(12px,7px,0) scale(1.03)}}
@keyframes v5qF2{from{transform:translate3d(14px,-8px,0) rotate(-.4deg)}to{transform:translate3d(-12px,9px,0) rotate(.4deg)}}
@keyframes v5qF3{from{transform:translate3d(-16px,10px,0)}to{transform:translate3d(18px,-10px,0)}}
.v5qsw{position:absolute;top:0;bottom:0;left:-100%;width:200%;pointer-events:none;will-change:transform;
 background:linear-gradient(104deg,rgba(255,255,255,0) 38%,rgba(255,255,255,.13) 47%,rgba(255,255,255,.2) 50%,rgba(255,255,255,.13) 53%,rgba(255,255,255,0) 62%);
 animation:v5qSw 13s cubic-bezier(.45,0,.55,1) infinite;transform:translate3d(-30%,0,0)}
@keyframes v5qSw{0%{transform:translate3d(-30%,0,0)}55%,100%{transform:translate3d(55%,0,0)}}
.cv-facetas .cv-logo span{background:linear-gradient(105deg,#fff 0%,#fff 40%,#b8ecff 46%,#fff 50%,#b8ecff 54%,#fff 60%,#fff 100%);background-size:320% 100%;background-position:100% 0;
 -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;
 animation:cvIn .7s cubic-bezier(.2,.8,.2,1) both,v5qSh 7s ease-in-out infinite;animation-delay:calc(var(--i)*70ms + 120ms),calc(var(--i)*90ms + 1.6s)}
@keyframes v5qSh{0%{background-position:100% 0}28%,100%{background-position:0% 0}}
html.v4lt .v5qf,html.v4lt .v5qsw{animation:none!important}html.v4lt .v5qsw{display:none}
html.v4lt .cv-facetas .cv-logo span{animation:cvIn .7s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i)*70ms + 120ms)}
@media (prefers-reduced-motion:reduce){.v5qf,.v5qsw,.cv-facetas .cv-logo span{animation:none!important}.v5qsw{display:none}}
